/bin/bash -lc "python - <<'PY'
from pathlib import Path
import shutil
p = Path('docs/specs/arch/ARCH-001.md')
shutil.copyfile(p, '/tmp/ARCH-001.before.md')
for f in Path('docs/specs').rglob('*.md'):
    if f "'!= p:
        shutil.copyfile(f, '"'/tmp/' + f.name + '.before')
try:
    import yaml
    print('PyYAML available for document validation')
except ImportError:
    print('PyYAML unavailable; use standard-library document checks')
s=p.read_text()
checks = {
    'amend outcome': 'outcome: amend' in s,
    'identity decision reopened': 'state: open\\n    resolved_by: []' in s,
    'current hosting decision cited': 'source: \"ADR-003\"' in s,
    'superseded decision not a resolver': 'resolved_by: [ADR-002]' not in s,
}
for name, passed in checks.items():
    print(('PASS' if passed else 'FAIL') + ': ' + name)
PY"

